fn numpy_isdtype(dtype: NumpyDType, kind: DTypeKind) -> bool {
    match kind {
        DTypeKind::Bool => {
            // Only Bool
            dtype == NumpyDType::Bool
        }
        DTypeKind::SignedInteger => {
            // Int8, Int16, Int32, Int64
            match dtype {
                NumpyDType::Int8
                | NumpyDType::Int16
                | NumpyDType::Int32
                | NumpyDType::Int64 => true,
                _ => false,
            }
        }
        DTypeKind::UnsignedInteger => {
            // UInt8, UInt16, UInt32, UInt64
            match dtype {
                NumpyDType::UInt8
                | NumpyDType::UInt16
                | NumpyDType::UInt32
                | NumpyDType::UInt64 => true,
                _ => false,
            }
        }
        DTypeKind::Integral => {
            // Any signed or unsigned integer
            match dtype {
                NumpyDType::Int8
                | NumpyDType::Int16
                | NumpyDType::Int32
                | NumpyDType::Int64
                | NumpyDType::UInt8
                | NumpyDType::UInt16
                | NumpyDType::UInt32
                | NumpyDType::UInt64 => true,
                _ => false,
            }
        }
        DTypeKind::RealFloating => {
            // Float16, Float32, Float64
            match dtype {
                NumpyDType::Float16
                | NumpyDType::Float32
                | NumpyDType::Float64 => true,
                _ => false,
            }
        }
        DTypeKind::ComplexFloating => {
            // Complex64, Complex128
            match dtype {
                NumpyDType::Complex64 | NumpyDType::Complex128 => true,
                _ => false,
            }
        }
        DTypeKind::Numeric => {
            // Bool, any integral, any real float, or any complex float
            match dtype {
                NumpyDType::Bool
                | NumpyDType::Int8
                | NumpyDType::Int16
                | NumpyDType::Int32
                | NumpyDType::Int64
                | NumpyDType::UInt8
                | NumpyDType::UInt16
                | NumpyDType::UInt32
                | NumpyDType::UInt64
                | NumpyDType::Float16
                | NumpyDType::Float32
                | NumpyDType::Float64
                | NumpyDType::Complex64
                | NumpyDType::Complex128 => true,
                _ => false,
            }
        }
    }
}